import java.util.*;

class Solution {
    static List<Integer> dedupeSorted(int[] ids) {
        List<Integer> result = new ArrayList<>();
        for (int value : ids) {
            if (result.isEmpty() || result.get(result.size() - 1) != value) result.add(value);
        }
        return result;
    }
}
